-- WorkMail D1 schema (SQLite) — canonical database schema.
-- Canonical database schema. Apply with: wrangler d1 execute <db> --file=db/schema.sql
-- then db/seed.sql. All ids are TEXT UUIDs generated by the app (see
-- lib/db.ts newId()); all timestamps are TEXT ISO-8601 (UTC).
-- Tenant isolation is enforced in APPLICATION CODE (lib/guards.ts +
-- membership checks in every route). D1 has no row-level security, so a
-- missing membership check is a real cross-tenant hole — the tenant
-- isolation test (tests/tenant-isolation.sql) must pass before launch.
-- Free-tier limits (live-verified 2026-11-21): D1 5 GB total, 5M rows
-- read/day, 100K rows written/day, no card required.

CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL UNIQUE,
  google_sub TEXT UNIQUE,
  display_name TEXT NOT NULL DEFAULT '',
  mfa_secret TEXT,
  pending_mfa_secret TEXT,
  suspended_at TEXT,
  suspension_reason TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS users_email_idx ON users(email);

CREATE TABLE IF NOT EXISTS sessions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash TEXT NOT NULL UNIQUE,
  expires_at TEXT NOT NULL,
  mfa_verified INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id);
CREATE INDEX IF NOT EXISTS sessions_token_idx ON sessions(token_hash);

CREATE TABLE IF NOT EXISTS workspaces (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  owner_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  suspended_at TEXT,
  suspension_reason TEXT,
  deleted_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS workspaces_owner_idx ON workspaces(owner_user_id);

CREATE TABLE IF NOT EXISTS memberships (
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role TEXT NOT NULL DEFAULT 'member' CHECK (role IN ('owner','admin','member','readonly')),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (workspace_id, user_id)
);
CREATE INDEX IF NOT EXISTS memberships_user_idx ON memberships(user_id);

CREATE TABLE IF NOT EXISTS domains (
  id TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  domain TEXT NOT NULL,
  ownership_status TEXT NOT NULL DEFAULT 'pending',
  dns_status TEXT NOT NULL DEFAULT 'pending',
  verification_token TEXT,
  created_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (workspace_id, domain)
);
CREATE INDEX IF NOT EXISTS domains_workspace_idx ON domains(workspace_id);

CREATE TABLE IF NOT EXISTS mailboxes (
  id TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  domain_id TEXT NOT NULL REFERENCES domains(id) ON DELETE CASCADE,
  address TEXT NOT NULL,
  display_name TEXT NOT NULL DEFAULT '',
  is_active INTEGER NOT NULL DEFAULT 1,
  created_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (workspace_id, address)
);
CREATE INDEX IF NOT EXISTS mailboxes_workspace_idx ON mailboxes(workspace_id);
CREATE INDEX IF NOT EXISTS mailboxes_domain_idx ON mailboxes(domain_id);
CREATE INDEX IF NOT EXISTS mailboxes_address_idx ON mailboxes(address);

CREATE TABLE IF NOT EXISTS mailbox_members (
  mailbox_id TEXT NOT NULL REFERENCES mailboxes(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  permission TEXT NOT NULL DEFAULT 'read_write' CHECK (permission IN ('read','read_write','manage')),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (mailbox_id, user_id)
);
CREATE INDEX IF NOT EXISTS mailbox_members_user_idx ON mailbox_members(user_id, mailbox_id);

CREATE TABLE IF NOT EXISTS messages (
  id TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  mailbox_id TEXT NOT NULL REFERENCES mailboxes(id) ON DELETE CASCADE,
  folder TEXT NOT NULL DEFAULT 'inbox',
  from_email TEXT NOT NULL,
  to_email TEXT NOT NULL,
  subject TEXT NOT NULL DEFAULT '',
  text_body TEXT NOT NULL DEFAULT '',
  html_body TEXT NOT NULL DEFAULT '',
  raw_object_key TEXT,
  is_read INTEGER NOT NULL DEFAULT 0,
  is_starred INTEGER NOT NULL DEFAULT 0,
  message_id TEXT,
  in_reply_to TEXT,
  thread_id TEXT,
  scheduled_at TEXT,
  deleted_at TEXT,
  provider TEXT,
  delivery_state TEXT NOT NULL DEFAULT 'received',
  received_at TEXT DEFAULT (datetime('now')),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS messages_mailbox_folder_date ON messages(mailbox_id, folder, received_at DESC);
CREATE INDEX IF NOT EXISTS messages_workspace_idx ON messages(workspace_id);
CREATE INDEX IF NOT EXISTS messages_thread_idx ON messages(mailbox_id, thread_id, received_at DESC);

CREATE TABLE IF NOT EXISTS provider_secrets (
  id TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  provider TEXT NOT NULL CHECK (provider IN ('brevo','mailjet','resend','sendpulse')),
  secret_ciphertext TEXT NOT NULL,
  key_version TEXT NOT NULL DEFAULT 'v1',
  enabled INTEGER NOT NULL DEFAULT 0,
  priority INTEGER NOT NULL DEFAULT 100,
  sender_verified INTEGER NOT NULL DEFAULT 0,
  last_test_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (workspace_id, provider)
);
CREATE INDEX IF NOT EXISTS provider_secrets_workspace_idx ON provider_secrets(workspace_id, priority);

CREATE TABLE IF NOT EXISTS idempotency_keys (
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  idempotency_key TEXT NOT NULL,
  request_hash TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'processing' CHECK (status IN ('processing','accepted','failed','unknown')),
  provider TEXT,
  provider_message_id TEXT,
  message_id TEXT REFERENCES messages(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (workspace_id, idempotency_key)
);
CREATE INDEX IF NOT EXISTS idempotency_message_idx ON idempotency_keys(message_id);

CREATE TABLE IF NOT EXISTS usage_counters (
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  period_start TEXT NOT NULL,
  sent_count INTEGER NOT NULL DEFAULT 0,
  received_count INTEGER NOT NULL DEFAULT 0,
  storage_bytes INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (workspace_id, period_start)
);

CREATE TABLE IF NOT EXISTS workspace_settings (
  workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id) ON DELETE CASCADE,
  plan TEXT NOT NULL DEFAULT 'free' CHECK (plan IN ('free','pro','business','enterprise')),
  monthly_send_limit INTEGER NOT NULL DEFAULT 300,
  retention_days INTEGER NOT NULL DEFAULT 90,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS platform_admins (
  user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  granted_at TEXT NOT NULL DEFAULT (datetime('now')),
  granted_by TEXT REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS security_events (
  id TEXT PRIMARY KEY,
  workspace_id TEXT REFERENCES workspaces(id) ON DELETE CASCADE,
  actor_user_id TEXT REFERENCES users(id),
  event_type TEXT NOT NULL,
  severity TEXT NOT NULL DEFAULT 'info',
  details TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS security_events_workspace_idx ON security_events(workspace_id, created_at DESC);
CREATE INDEX IF NOT EXISTS security_events_actor_idx ON security_events(actor_user_id);

CREATE TABLE IF NOT EXISTS message_attachments (
  id TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  mailbox_id TEXT NOT NULL REFERENCES mailboxes(id) ON DELETE CASCADE,
  message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
  file_name TEXT NOT NULL,
  content_type TEXT NOT NULL,
  size_bytes INTEGER NOT NULL,
  object_key TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS message_attachments_message_idx ON message_attachments(message_id);
CREATE INDEX IF NOT EXISTS message_attachments_workspace_idx ON message_attachments(workspace_id);

CREATE TABLE IF NOT EXISTS labels (
  id TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  mailbox_id TEXT REFERENCES mailboxes(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  color TEXT NOT NULL DEFAULT '#64748b',
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (workspace_id, mailbox_id, name)
);

CREATE TABLE IF NOT EXISTS message_labels (
  message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
  label_id TEXT NOT NULL REFERENCES labels(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (message_id, label_id)
);

CREATE TABLE IF NOT EXISTS contacts (
  id TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  email TEXT NOT NULL,
  name TEXT NOT NULL DEFAULT '',
  company TEXT NOT NULL DEFAULT '',
  notes TEXT NOT NULL DEFAULT '',
  created_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (workspace_id, email)
);

CREATE TABLE IF NOT EXISTS mail_rules (
  id TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  mailbox_id TEXT REFERENCES mailboxes(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  conditions TEXT NOT NULL DEFAULT '{}',
  actions TEXT NOT NULL DEFAULT '{}',
  is_enabled INTEGER NOT NULL DEFAULT 1,
  created_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS delivery_events (
  id TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  message_id TEXT REFERENCES messages(id) ON DELETE SET NULL,
  provider TEXT NOT NULL,
  provider_event_id TEXT,
  event_type TEXT NOT NULL CHECK (event_type IN ('accepted','sent','delivered','deferred','bounced','complained','rejected','opened','clicked','unknown')),
  recipient TEXT,
  details TEXT NOT NULL DEFAULT '{}',
  occurred_at TEXT NOT NULL DEFAULT (datetime('now')),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (provider, provider_event_id)
);

CREATE TABLE IF NOT EXISTS suppressions (
  id TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  email TEXT NOT NULL,
  reason TEXT NOT NULL CHECK (reason IN ('hard_bounce','complaint','unsubscribe','manual')),
  source TEXT NOT NULL DEFAULT 'system',
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (workspace_id, email)
);

CREATE TABLE IF NOT EXISTS outbound_jobs (
  id TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  message_id TEXT REFERENCES messages(id) ON DELETE CASCADE,
  idempotency_key TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','processing','accepted','delivered','retry','failed','unknown')),
  attempts INTEGER NOT NULL DEFAULT 0,
  next_attempt_at TEXT DEFAULT (datetime('now')),
  last_error TEXT,
  locked_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (workspace_id, idempotency_key)
);
CREATE INDEX IF NOT EXISTS outbound_jobs_due_idx ON outbound_jobs(status, next_attempt_at) WHERE status IN ('queued','retry');

CREATE TABLE IF NOT EXISTS plan_catalog (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  monthly_price_minor INTEGER NOT NULL DEFAULT 0,
  currency TEXT NOT NULL DEFAULT 'INR',
  monthly_send_limit INTEGER NOT NULL,
  storage_limit_bytes INTEGER NOT NULL,
  features TEXT NOT NULL DEFAULT '{}',
  is_active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS subscriptions (
  id TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  plan_id TEXT NOT NULL REFERENCES plan_catalog(id),
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','active','past_due','cancelled','expired')),
  billing_provider TEXT,
  provider_subscription_id TEXT,
  period_start TEXT,
  period_end TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE UNIQUE INDEX IF NOT EXISTS subscriptions_one_active_idx ON subscriptions(workspace_id) WHERE status IN ('pending','active','past_due');

CREATE TABLE IF NOT EXISTS invoices (
  id TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  subscription_id TEXT REFERENCES subscriptions(id) ON DELETE SET NULL,
  amount_minor INTEGER NOT NULL,
  currency TEXT NOT NULL DEFAULT 'INR',
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','paid','failed','refunded')),
  payment_reference TEXT,
  issued_at TEXT NOT NULL DEFAULT (datetime('now')),
  paid_at TEXT,
  metadata TEXT NOT NULL DEFAULT '{}'
);

CREATE TABLE IF NOT EXISTS admin_actions (
  id TEXT PRIMARY KEY,
  admin_user_id TEXT REFERENCES users(id),
  action TEXT NOT NULL,
  target_workspace_id TEXT REFERENCES workspaces(id) ON DELETE SET NULL,
  details TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS audit_events (
  id TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  actor_user_id TEXT REFERENCES users(id),
  action TEXT NOT NULL,
  target_type TEXT NOT NULL,
  target_id TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS audit_events_workspace_idx ON audit_events(workspace_id);

CREATE TABLE IF NOT EXISTS platform_user_controls (
  user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  suspended_at TEXT,
  suspension_reason TEXT,
  mfa_required INTEGER NOT NULL DEFAULT 1,
  updated_by TEXT REFERENCES users(id),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS plan_change_log (
  id TEXT PRIMARY KEY,
  workspace_id TEXT REFERENCES workspaces(id) ON DELETE CASCADE,
  plan_id TEXT NOT NULL,
  changed_by TEXT REFERENCES users(id),
  before_state TEXT,
  after_state TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS payment_events (
  id TEXT PRIMARY KEY,
  invoice_id TEXT REFERENCES invoices(id) ON DELETE SET NULL,
  workspace_id TEXT REFERENCES workspaces(id) ON DELETE CASCADE,
  provider TEXT NOT NULL DEFAULT 'manual',
  provider_event_id TEXT,
  event_type TEXT NOT NULL,
  amount_minor INTEGER,
  currency TEXT DEFAULT 'INR',
  verified INTEGER NOT NULL DEFAULT 0,
  payload TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (provider, provider_event_id)
);
CREATE INDEX IF NOT EXISTS payment_events_invoice_idx ON payment_events(invoice_id);
CREATE INDEX IF NOT EXISTS payment_events_workspace_idx ON payment_events(workspace_id);

CREATE TABLE IF NOT EXISTS backup_runs (
  id TEXT PRIMARY KEY,
  backup_kind TEXT NOT NULL,
  status TEXT NOT NULL,
  object_key TEXT,
  checksum TEXT,
  bytes INTEGER,
  started_at TEXT NOT NULL DEFAULT (datetime('now')),
  finished_at TEXT,
  details TEXT NOT NULL DEFAULT '{}'
);

CREATE TABLE IF NOT EXISTS monitor_checks (
  id TEXT PRIMARY KEY,
  check_name TEXT NOT NULL,
  status TEXT NOT NULL,
  latency_ms INTEGER,
  details TEXT NOT NULL DEFAULT '{}',
  checked_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS dns_change_log (
  id TEXT PRIMARY KEY,
  workspace_id TEXT REFERENCES workspaces(id) ON DELETE CASCADE,
  domain_id TEXT REFERENCES domains(id) ON DELETE CASCADE,
  provider TEXT NOT NULL,
  action TEXT NOT NULL,
  record_name TEXT,
  record_type TEXT,
  record_content TEXT,
  actor TEXT REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS dns_change_log_workspace_idx ON dns_change_log(workspace_id);

-- updated_at maintenance (SQLite triggers; the previous migrations
-- added updated_at columns but never maintained them).
CREATE TRIGGER IF NOT EXISTS users_updated_at AFTER UPDATE ON users FOR EACH ROW BEGIN UPDATE users SET updated_at = datetime('now') WHERE id = NEW.id; END;
CREATE TRIGGER IF NOT EXISTS messages_updated_at AFTER UPDATE ON messages FOR EACH ROW BEGIN UPDATE messages SET updated_at = datetime('now') WHERE id = NEW.id; END;
CREATE TRIGGER IF NOT EXISTS contacts_updated_at AFTER UPDATE ON contacts FOR EACH ROW BEGIN UPDATE contacts SET updated_at = datetime('now') WHERE id = NEW.id; END;
CREATE TRIGGER IF NOT EXISTS subscriptions_updated_at AFTER UPDATE ON subscriptions FOR EACH ROW BEGIN UPDATE subscriptions SET updated_at = datetime('now') WHERE id = NEW.id; END;
CREATE TRIGGER IF NOT EXISTS outbound_jobs_updated_at AFTER UPDATE ON outbound_jobs FOR EACH ROW BEGIN UPDATE outbound_jobs SET updated_at = datetime('now') WHERE id = NEW.id; END;
CREATE TRIGGER IF NOT EXISTS idempotency_updated_at AFTER UPDATE ON idempotency_keys FOR EACH ROW BEGIN UPDATE idempotency_keys SET updated_at = datetime('now') WHERE id = NEW.id; END;
CREATE TRIGGER IF NOT EXISTS user_controls_updated_at AFTER UPDATE ON platform_user_controls FOR EACH ROW BEGIN UPDATE platform_user_controls SET updated_at = datetime('now') WHERE user_id = NEW.user_id; END;

-- New workspace gets a free subscription (replaces the previous database trigger).
CREATE TRIGGER IF NOT EXISTS workspace_default_subscription AFTER INSERT ON workspaces FOR EACH ROW BEGIN
  INSERT OR IGNORE INTO subscriptions (id, workspace_id, plan_id, status, created_at, updated_at)
  VALUES (lower(hex(randomblob(16))), NEW.id, 'free', 'active', datetime('now'), datetime('now'));
END;

-- New mailbox auto-assigns the workspace owner as manager.
CREATE TRIGGER IF NOT EXISTS mailbox_owner_access AFTER INSERT ON mailboxes FOR EACH ROW BEGIN
  INSERT OR IGNORE INTO mailbox_members (mailbox_id, user_id, permission)
  SELECT NEW.id, w.owner_user_id, 'manage' FROM workspaces w WHERE w.id = NEW.workspace_id;
  INSERT OR IGNORE INTO mailbox_members (mailbox_id, user_id, permission)
  SELECT NEW.id, NEW.created_by, 'manage' WHERE NEW.created_by IS NOT NULL;
END;

-- ==========================================================================
-- Gap-fix migrations (2026-11-21) — ADDITIVE ONLY. Apply after the base
-- schema above (wrangler d1 execute <db> --file=db/schema.sql). These
-- statements are one-time migrations: re-running the ALTER TABLE lines
-- against a database that already has the columns fails with
-- "duplicate column name" — that is expected and harmless; the CREATE
-- TABLE IF NOT EXISTS lines are safe to re-run.
-- ==========================================================================

-- G-23: outbound_jobs needs the original send payload (so the retry
-- worker can re-send) and the provider that handled the last attempt.
-- `status` already allows queued/processing/accepted/delivered/retry/
-- failed/unknown; `attempts` and `next_attempt_at` already exist.
ALTER TABLE outbound_jobs ADD COLUMN provider TEXT;
ALTER TABLE outbound_jobs ADD COLUMN payload TEXT NOT NULL DEFAULT '{}';

-- G-28: MFA recovery codes. Single-use, stored ONLY as SHA-256 hashes
-- (see lib/mfa.ts generateRecoveryCodes/hashRecoveryCode). Plain codes
-- are shown once at enrolment/regeneration and never stored or logged.
-- A used code is burned by setting used_at; verification only accepts
-- rows with used_at IS NULL.
CREATE TABLE IF NOT EXISTS recovery_codes (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  code_hash TEXT NOT NULL,
  used_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (user_id, code_hash)
);
CREATE INDEX IF NOT EXISTS recovery_codes_user_idx ON recovery_codes(user_id, used_at);
